using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "EntropyHoodOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/EntropyHood Omen Data")]
public class EntropyHoodOmenData : OnStartOfBattleOmenData
{
	[SerializeField]
	private int purifyIncreaseValue;

	public override void Initialize(OmenInstance omenInstance)
	{
		base.Initialize(omenInstance);
		ReferenceSingleton<MiscOmensHandler>.Instance.EntropyHoodOmenAction = (int value) => (value == 1) ? purifyIncreaseValue : value;
	}

	public override void OmenRemoved()
	{
		base.OmenRemoved();
		ReferenceSingleton<MiscOmensHandler>.Instance.EntropyHoodOmenAction = null;
	}

	public override string OmenConvertedDescription()
	{
		return Smart.Format(GetOmenRawLocalizedDescription(), purifyIncreaseValue) + "\n" + base.OmenConvertedDescription();
	}
}
